using System.Drawing;using System.Windows.Forms;
namespace LSE.AutoCADElectrical.ProjectDoctor;
public sealed class DoctorSettingsForm:Form{readonly AppSettings s=SettingsService.Load();readonly Dictionary<string,TextBox> boxes=new();readonly Dictionary<string,CheckBox> checks=new();readonly ToolTip tips=new(){AutoPopDelay=30000,InitialDelay=300,ReshowDelay=100};
 public DoctorSettingsForm(){Text=BuildInfo.Title("settings");StartPosition=FormStartPosition.CenterParent;Size=new Size(1000,660);MinimumSize=new Size(760,520);var p=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=3,Padding=new Padding(12),AutoScroll=true};p.ColumnStyles.Add(new(SizeType.Absolute,230));p.ColumnStyles.Add(new(SizeType.Percent,100));p.ColumnStyles.Add(new(SizeType.Absolute,100));int r=0;
  Add(p,"Template project (.wdp) = the standard",nameof(s.TemplateProjectPath),s.TemplateProjectPath,r++,"The LSE custom project template on the Vault working folder. Its .wdp, .wdt, _wdtitle.wdl and DRAWING-#.dwg define what correct means. If the path is wrong a bundled copy of the text files is used and drawing repairs are not possible.","AutoCAD Electrical project (*.wdp)|*.wdp");
  Add(p,"Doctor rules JSON",nameof(s.RulesConfigPath),s.RulesConfigPath,r++,"How strictly to compare: enforce options, properties, mappings, labels and wire layers; protected lines; purge unused wire layers. Blank = the LseDoctorRules.json next to the plugin DLL.","JSON (*.json)|*.json");
  Add(p,"Projects root (scan default)",nameof(s.ProjectsRootFolder),s.ProjectsRootFolder,r++,"The folder LSEDOCTORSCAN starts in.","folder");
  Add(p,"Backup folder name (inside the project)",nameof(s.BackupFolderName),s.BackupFolderName,r++,"Created inside each project folder before a repair; one subfolder per repair, named by date and time.");
  Add(p,"Backups to keep per project",nameof(s.BackupsToKeep),s.BackupsToKeep.ToString(),r++,"Older backup folders are removed after a successful repair. 1 or more.");
  Add(p,"Active project LISP (sets USERS1)",nameof(s.ActiveProjectLisp),s.ActiveProjectLisp,r++,"The AutoCAD Electrical call used to find the active project. Leave it unless support asks you to change it.");
  Add(p,"Reload project LISP ({WDP})",nameof(s.ActivateProjectLisp),s.ActivateProjectLisp,r++,"The call used to reload the active project after a repair; {WDP} is replaced by the project path. Leave it unless support asks you to change it.");
  Check(p,"Check drawing contents by default (LSEDOCTOR)",nameof(s.CheckDrawings),s.CheckDrawings,r++,"Whether Check every drawing starts ticked in the Doctor window.");
  Check(p,"Recommend inserting a missing WD_M block from the template drawing",nameof(s.InsertMissingWdm),s.InsertMissingWdm,r++,"Whether a drawing without a WD_M block is ticked for repair by default.");
  Check(p,"Folder scan checks drawing contents too (slow)",nameof(s.ScanChecksDrawings),s.ScanChecksDrawings,r++,"Whether LSEDOCTORSCAN opens every drawing of every project.");
  Check(p,"Reload the active project after it is repaired",nameof(s.ReactivateAfterRepair),s.ReactivateAfterRepair,r++,"So the Project Manager shows the repaired settings when the Doctor window closes.");
  Check(p,"Show the repair report after each repair",nameof(s.ShowReportAfterRepair),s.ShowReportAfterRepair,r++,"The log window after Repair ticked.");
  var save=new Button{Text="Save",Width=100,Height=36};save.Click+=(_,_)=>{try{s.TemplateProjectPath=boxes[nameof(s.TemplateProjectPath)].Text.Trim();s.RulesConfigPath=boxes[nameof(s.RulesConfigPath)].Text.Trim();s.ProjectsRootFolder=boxes[nameof(s.ProjectsRootFolder)].Text.Trim();s.BackupFolderName=boxes[nameof(s.BackupFolderName)].Text.Trim();s.ActiveProjectLisp=boxes[nameof(s.ActiveProjectLisp)].Text.Trim();s.ActivateProjectLisp=boxes[nameof(s.ActivateProjectLisp)].Text.Trim();
   if(!int.TryParse(boxes[nameof(s.BackupsToKeep)].Text.Trim(),out int keep)||keep<1)throw new InvalidOperationException("Backups to keep must be a whole number of 1 or more.");s.BackupsToKeep=keep;if(s.BackupFolderName.Length==0||s.BackupFolderName.IndexOfAny(Path.GetInvalidFileNameChars())>=0)throw new InvalidOperationException("Backup folder name must be a valid folder name.");
   s.CheckDrawings=checks[nameof(s.CheckDrawings)].Checked;s.InsertMissingWdm=checks[nameof(s.InsertMissingWdm)].Checked;s.ScanChecksDrawings=checks[nameof(s.ScanChecksDrawings)].Checked;s.ReactivateAfterRepair=checks[nameof(s.ReactivateAfterRepair)].Checked;s.ShowReportAfterRepair=checks[nameof(s.ShowReportAfterRepair)].Checked;SettingsService.Save(s);DialogResult=DialogResult.OK;Close();}catch(Exception ex){MessageBox.Show(ex.Message,"LSE_Doctor Settings");}};
  var help=new Button{Text="Help",Width=100,Height=36};help.Click+=(_,_)=>{using var f=new TextReportForm("LSE_Doctor - settings help",HelpText.Fix(HelpText.Settings),true);f.ShowDialog(this);};
  var diag=new Button{Text="Diagnostics",Dock=DockStyle.Fill};diag.Click+=(_,_)=>{using var f=new TextReportForm("LSE_Doctor Diagnostics",DiagnosticsService.BuildReport());f.ShowDialog(this);};
  var bar=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft,WrapContents=false};bar.Controls.Add(save);bar.Controls.Add(help);p.RowStyles.Add(new(SizeType.Absolute,48));p.Controls.Add(diag,0,r);p.Controls.Add(bar,1,r);p.SetColumnSpan(bar,2);Controls.Add(p);
  tips.SetToolTip(save,"Write the settings to %APPDATA%\\LSE\\LSE_Doctor\\settings.json and close.");tips.SetToolTip(help,"What every setting means.");tips.SetToolTip(diag,"Runtime, settings, rules and whether the standard parses. Paste it into a trouble report.");CancelButton=null;}
 void Add(TableLayoutPanel p,string label,string key,string value,int row,string tip,string? browse=null){p.RowStyles.Add(new(SizeType.Absolute,48));var l=new Label{Text=label,AutoSize=true,Anchor=AnchorStyles.Left};p.Controls.Add(l,0,row);var t=new TextBox{Text=value,Dock=DockStyle.Fill};boxes[key]=t;p.Controls.Add(t,1,row);tips.SetToolTip(l,tip);tips.SetToolTip(t,tip);if(browse is null)return;var b=new Button{Text="Browse",Dock=DockStyle.Fill};b.Click+=(_,_)=>{if(browse=="folder"){using var f=new FolderBrowserDialog{SelectedPath=Directory.Exists(t.Text)?t.Text:""};if(f.ShowDialog()==DialogResult.OK)t.Text=f.SelectedPath;}else{using var f=new OpenFileDialog{Filter=browse,FileName=t.Text};if(f.ShowDialog()==DialogResult.OK)t.Text=f.FileName;}};p.Controls.Add(b,2,row);tips.SetToolTip(b,browse=="folder"?"Pick a folder.":"Pick a file.");}
 void Check(TableLayoutPanel p,string label,string key,bool value,int row,string tip){p.RowStyles.Add(new(SizeType.Absolute,34));var c=new CheckBox{Text=label,Checked=value,AutoSize=true,Anchor=AnchorStyles.Left};checks[key]=c;p.Controls.Add(c,1,row);p.SetColumnSpan(c,2);tips.SetToolTip(c,tip);}
}
